using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip using that metadata:
var alice = new Person("Alice", 30);
string json = JsonSerializer.Serialize(alice, personInfo);
Console.WriteLine($"Serialized: {json}");

Person? deserialized = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false when unavailable.
//    Use an empty resolver so nothing is resolved.
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (info) => throw new NotSupportedException() }
    }
};

// For a type the resolver *can't* provide, TryGetTypeInfo returns false.
bool found = restricted.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine($"\nTryGetTypeInfo on restricted resolver → found: {found}, info: {probed?.Type.Name ?? "(null)"}");

// Compare with the working resolver:
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed2);
Console.WriteLine($"TryGetTypeInfo on normal resolver   → found: {found2}, info: {probed2?.Type.Name ?? "(null)"}");

public record Person(string Name, int Age);

